def task_func(url=URL, from_encoding="cp1251", use_lxml=False):
    if not url:
        return None
    try:
        response = requests.get(url)
        if response.status_code != 200:
            return None
        response.encoding = from_encoding
        content = response.text
    except requests.RequestException:
        return None
    except UnicodeDecodeError:
        return None
    try:
        if use_lxml:
            soup = BeautifulSoup(content, 'lxml')
        else:
            soup = BeautifulSoup(content, 'html.parser')
        return soup
    except Exception:
        return None

import json
import requests
import chardet
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content
    if not content:
        return {}
    if from_encoding is None:
        detected = chardet.detect(content)
        if not detected.get('encoding'):
            raise ValueError("Unable to detect encoding for non-empty content")
        from_encoding = detected['encoding']
    decoded = content.decode(from_encoding)
    encoded = decoded.encode(to_encoding)
    return json.loads(encoded)

import requests
import logging
def task_func(repo_url: str) -> dict:
