import requests
import os
import zipfile
def task_func(url, destination_directory, headers=None):
    if headers is None:
        headers = {}
    os.makedirs(destination_directory, exist_ok=True)
    local_zip_path = os.path.join(destination_directory, 'temp_download.zip')
    try:
        response = requests.get(url, headers=headers, stream=True, timeout=30)
        response.raise_for_status()
        with open(local_zip_path, 'wb') as f:
            for chunk in response.iter_content(chunk_size=8192):
                if chunk:
                    f.write(chunk)
    except requests.exceptions.RequestException as e:
        raise RuntimeError(f"Failed to download file from {url}: {e}")
    if not zipfile.is_zipfile(local_zip_path):
        raise RuntimeError(f"Downloaded file is not a valid zip archive.")
    extracted_files = []
    try:
        with zipfile.ZipFile(local_zip_path, 'r') as zip_ref:
            zip_ref.extractall(destination_directory)
            extracted_files = zip_ref.namelist()
    except zipfile.BadZipFile as e:
        raise RuntimeError(f"Failed to extract zip file: {e}")
    finally:
        if os.path.exists(local_zip_path):
            os.remove(local_zip_path)
    return extracted_files

import requests
import json
import pandas as pd
import seaborn as sns
import matplotlib.pyplot as plt

HEADERS = {
    'accept': 'application/json'
}
def task_func(url, parameters):
    if not isinstance(url, str) or not url.strip():
        raise Exception("Invalid URL provided.")
    if not isinstance(parameters, dict):
        raise Exception("Invalid parameters provided.")
    try:
        response = requests.get(url, params=parameters, headers=HEADERS)
        response.raise_for_status()
        data = response.json()
        if not data:
            raise Exception("No data returned from API.")
    except requests.RequestException as e:
        raise Exception(f"Failed to retrieve data: {e}")
    df = pd.DataFrame(data)
    numeric_cols = df.select_dtypes(include=['number']).columns
    if len(numeric_cols) < 2:
        raise Exception("Insufficient numerical data for correlation.")
    corr_matrix = df[numeric_cols].corr()
    fig, ax = plt.subplots(figsize=(10, 8))
    sns.heatmap(corr_matrix, annot=True, fmt=".2f", cmap='coolwarm', ax=ax)
    ax.set_title('Correlation Heatmap')
    return df, ax

import unicodedata
import requests
URL = 'https://api.github.com/users/'
def task_func(username):
    response = requests.get(f"{URL}{username}")
    response.raise_for_status()
    data = response.json()
    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, str):
            normalized_value = unicodedata.normalize('NFKD', value).encode('ascii', 'ignore').decode('ascii')
            normalized_data[key] = normalized_value
        else:
            normalized_data[key] = value
    return normalized_data

from flask import Flask
from flask_restful import Resource, Api
import requests
def task_func(api_url, template_folder):
    app = Flask(__name__, template_folder=template_folder)
    api = Api(app)
    class APIEndpoint(Resource):
        def get(self):
            try:
                response = requests.get(api_url)
                response.raise_for_status()
                return response.json()
            except requests.RequestException as e:
                return {'error': str(e)}, 400
    api.add_resource(APIEndpoint, '/')
    return app
